package com.portablediag.permafrost.ui;

import com.portablediag.permafrost.R;

/**
 * The house palettes, in the picker's order. GENERATED by tools/gen_palettes.py
 * from ProjectForge palettes.toml — do not edit; regenerate.
 *
 * <p>Saved by {@link #id} (the house name), never by position, so adding or
 * reordering palettes never changes the one a user picked.
 */
public enum Palette {
    MATERIAL_YOU("Material You", "Material You (wallpaper colours)", true, false,
            0, 0, false),
    OCEAN("Ocean", "Ocean", true, false,
            R.style.ThemeOverlay_Permafrost_Palette_Ocean, R.style.ThemeOverlay_Permafrost_Palette_Ocean_Light, false),
    TERMINAL("Terminal", "Terminal", true, true,
            R.style.ThemeOverlay_Permafrost_Palette_Terminal, R.style.ThemeOverlay_Permafrost_Palette_Terminal_Light, false),
    TRELLIS("Trellis", "Trellis", false, false,
            R.style.ThemeOverlay_Permafrost_Palette_Trellis, 0, false),
    GRAPHITE("Graphite", "Graphite", false, false,
            R.style.ThemeOverlay_Permafrost_Palette_Graphite, 0, false),
    BLUEPRINT("Blueprint", "Blueprint", false, false,
            R.style.ThemeOverlay_Permafrost_Palette_Blueprint, 0, false),
    FUTURISTIC("Futuristic", "Futuristic", false, false,
            R.style.ThemeOverlay_Permafrost_Palette_Futuristic, 0, false),
    NEON("Neon", "Neon", false, false,
            R.style.ThemeOverlay_Permafrost_Palette_Neon, 0, false),
    SYNTHWAVE("SynthWave", "SynthWave", false, false,
            R.style.ThemeOverlay_Permafrost_Palette_SynthWave, 0, false),
    WHITE_GLOW("White Glow", "White Glow", false, false,
            R.style.ThemeOverlay_Permafrost_Palette_WhiteGlow, 0, false),
    SILKSCREEN("Silkscreen", "Silkscreen", false, false,
            R.style.ThemeOverlay_Permafrost_Palette_Silkscreen, 0, false),
    STICKY_NOTES("Sticky Notes", "Sticky Notes", false, false,
            R.style.ThemeOverlay_Permafrost_Palette_StickyNotes, 0, true),
    AMBER_TERMINAL("Amber Terminal", "Amber Terminal", false, true,
            R.style.ThemeOverlay_Permafrost_Palette_AmberTerminal, 0, false),
    PHOSPHOR_GREEN("Phosphor Green", "Phosphor Green", false, true,
            R.style.ThemeOverlay_Permafrost_Palette_PhosphorGreen, 0, false),
    PHOSPHOR_P31("Phosphor P31", "Phosphor P31", false, true,
            R.style.ThemeOverlay_Permafrost_Palette_PhosphorP31, 0, false),
    ZORO("Zoro", "Zoro", false, false,
            R.style.ThemeOverlay_Permafrost_Palette_Zoro, 0, false),
    NEBULA("Nebula", "Nebula", false, false,
            R.style.ThemeOverlay_Permafrost_Palette_Nebula, 0, false);

    /** The house name — what is saved, and what the API takes. */
    public final String id;
    public final String label;
    /** Has both a light and a dark form, so the light/dark setting applies. */
    public final boolean followsMode;
    /** Sets the whole type ramp in monospace. */
    public final boolean mono;
    /** Theme overlay for the dark (or only) form; 0 for Material You. */
    final int darkStyle;
    /** Theme overlay for the light form; 0 when there is none. */
    final int lightStyle;
    /** The only form is a light one (dark status-bar icons). */
    final boolean lightOnly;

    Palette(String id, String label, boolean followsMode, boolean mono,
            int darkStyle, int lightStyle, boolean lightOnly) {
        this.id = id;
        this.label = label;
        this.followsMode = followsMode;
        this.mono = mono;
        this.darkStyle = darkStyle;
        this.lightStyle = lightStyle;
        this.lightOnly = lightOnly;
    }

    public boolean isDynamic() {
        return darkStyle == 0;
    }

    /** Looks a palette up by its house name, ignoring case; the fallback when unknown. */
    public static Palette fromId(String id, Palette fallback) {
        if (id == null) return fallback;
        for (Palette p : values()) {
            if (p.id.equalsIgnoreCase(id.trim())) return p;
        }
        return fallback;
    }
}
